    "summary": "استقر الأنباط جنوبي الأردن في القرن السادس قبل الميلاد تقريباً بعد هجرتهم من شبه الجزيرة العربية، واتخذوا من البترا عاصمة حصينة لهم تميزت بموقعها الاستراتيجي على الطرق التجارية ووفرة مياهها. امتدت مملكتهم من مدائن صالح جنوباً حتى دمشق شمالاً، وحكمها نظام ملكي وراثي برز فيه ملوك عظام كعبادة الأول والحارث الثالث والحارث الرابع، كما نالت المرأة حقوقاً مميزة كالتملك وإدارة الحكم مثل الملكة (شقيلات). وقد أبدع الأنباط في الجانب المعماري بنحت الصخور واستخدام الأحجار المشذبة في معالم كالدير والخزنة، بالإضافة إلى تشييد مدينة أم الجمال من الحجر البازلتي الأسود والتي تميزت بنظام فريد للحصاد المائي والتصريف الصحي وأُدرجت على لائحة التراث العالمي عام 2024م.\n\nوفي الجانب الاقتصادي، أظهر الأنباط عبقرية هندسية استثنائية في الري والحصاد المائي من خلال حفر الخزانات الصخرية وبناء السدود الاعتراضية وقنوات الفخار لجر المياه، مما مكنهم من تطوير زراعة متقدمة على المصاطب الجبلية لحماية التربة. كما ازدهرت صناعاتهم كالفخار النبطي الرقيق المزين بالزخارف واستخراج النحاس والملح والقار، ونمت تجارتهم بفضل موقعهم المتوسط وتأمينهم للقوافل بواسطة الحاميات العسكرية والمحطات التجارية. إلا أن عوامل الضعف الداخلي، والسيطرة الرومانية على الطرق التجارية وتحويلها نحو مدينة تدمر، أدت في النهاية إلى سقوط البترا واحتلالها من قبل الإمبراطور الروماني تراجان عام 106م وضمها للولاية العربية التابعة لروما.",
